    "        let envp: int = Memory.Alloc(8);\n"
    "        Memory.Write64(envp, 0);\n"
    "        Kernel.Call(59, path, argv, envp);\n"
    "        Kernel.Call(60, 127);\n"
    "    }\n"
    "    return pid;\n"
    "}\n"
    "\n"
    "fn pc_spawn4(path, a1, a2, a3, a4) {\n"
    "    if path == 0 { return -1; }\n"
    "    let pid: int = Kernel.Call(57);\n"
    "    if pid < 0 { return -1; }\n"
    "    if pid == 0 {\n"
    "        let argv: int = Memory.Alloc(56);\n"
    "        Memory.Write64(argv, path);\n"
    "        Memory.Write64(argv + 8, a1);\n"
    "        Memory.Write64(argv + 16, a2);\n"
    "        Memory.Write64(argv + 24, a3);\n"
    "        Memory.Write64(argv + 32, a4);\n"
    "        Memory.Write64(argv + 40, 0);\n"
    "        let envp: int = Memory.Alloc(8);\n"
    "        Memory.Write64(envp, 0);\n"
    "        Kernel.Call(59, path, argv, envp);\n"
    "        Kernel.Call(60, 127);\n"
    "    }\n"
    "    return pid;\n"
    "}\n"
    "\n"
    "fn pc_spawn_wait(path, arg1) {\n"
    "    let pid: int = pc_spawn(path, arg1);\n"
    "    if pid <= 0 { return pid; }\n"
    "    let st: int = Rt.Global() + 256;\n"
    "    Kernel.Call(61, pid, st, 0, 0);\n"
    "    return 0;\n"
    "}\n"
    "\n"
    "fn pc_waitpid(pid) {\n"
    "    if pid <= 0 { return -1; }\n"
    "    let st: int = Rt.Global() + 256;\n"
    "    Kernel.Call(61, pid, st, 0, 0);\n"
    "    return Memory.Read32(st);\n"
    "}\n"
    "\n"
    "// ---- Web.JS.Run / Web.HTML.Load\n"
    "\n"
    "fn Web.JS.Run(path) {\n"
    "    if path == 0 { return -1; }\n"
    "    let r: int = pc_spawn_wait(\"/usr/bin/node\", path);\n"
    "    if r < 0 { r = pc_spawn_wait(\"/usr/bin/nodejs\", path); }\n"
    "    return r;\n"
    "}\n"
    "\n"
    "fn Web.HTML.Load(path) {\n"
    "    if path == 0 { return -1; }\n"
    "    let r: int = pc_spawn_wait(\"/usr/bin/xdg-open\", path);\n"
    "    if r < 0 { r = pc_spawn_wait(\"/usr/bin/open\", path); }\n"
    "    return r;\n"
    "}\n"
    "\n"
    "// ---- Net.HttpsGet(host, path, outfile) — real fetch via curl (system TLS/CA store)\n"
    "\n"
    "fn Net.HttpsGet(host, path, outfile) {\n"
    "    if host == 0 { return -1; }\n"
    "    if path == 0 { path = \"/\"; }\n"
    "    // Build https://host/path\n"
    "    let url: int = Memory.Alloc(pc_strlen(host) + pc_strlen(path) + 16);\n"
    "    let off: int = pc_cat(url, 0, \"https://\");\n"
    "    off = pc_cat(url, off, host);\n"
    "    if Memory.Read8(path) != 47 { off = pc_cat(url, off, \"/\"); }\n"
    "    off = pc_cat(url, off, path);\n"
    "\n"
    "    let out: int = outfile;\n"
    "    if out == 0 { out = \"-\"; }\n"
    "    // Prefer curl -sL -o outfile url  (or stdout when outfile is \"-\")\n"
    "    let pid: int = 0;\n"
    "    if pc_strcmp(out, \"-\") == 0 {\n"
    "        // curl -sL url  (stdout)\n"
    "        pid = pc_spawn2(\"/usr/bin/curl\", \"-sL\", url);\n"
    "        if pid < 0 { pid = pc_spawn2(\"/bin/curl\", \"-sL\", url); }\n"
    "    } else {\n"
    "        pid = pc_spawn4(\"/usr/bin/curl\", \"-sL\", \"-o\", out, url);\n"
    "        if pid < 0 { pid = pc_spawn4(\"/bin/curl\", \"-sL\", \"-o\", out, url); }\n"
    "    }\n"
    "    Memory.Free(url);\n"
    "    if pid < 0 {\n"
    "        let msg = \"[Net.HttpsGet] curl not found; install curl or use --gcc for OpenSSL path\\n\";\n"
    "        pc_write_all(2, msg, pc_strlen(msg));\n"
    "        return -1;\n"
    "    }\n"
    "    let st: int = pc_waitpid(pid);\n"
    "    // wait status: if exited with 0, success. Approximate body size from file.\n"
    "    if out != 0 {\n"
    "        if pc_strcmp(out, \"-\") != 0 {\n"
    "            let sz: int = File.Size(out);\n"
    "            if sz >= 0 { Memory.Write64(Rt.Global(), 200); return sz; }\n"
    "        }\n"
    "    }\n"
    "    if st == 0 { Memory.Write64(Rt.Global(), 200); return 0; }\n"
    "    Memory.Write64(Rt.Global(), 0);\n"
    "    return -1;\n"
    "}\n"
    "\n"
    "// ---- Image.Load / Image.Show — PPM natively; PNG/JPEG via convert → PPM\n"
    "\n"
    "fn pc_is_ppm(path) {\n"
    "    let fd: int = Kernel.Call(2, path, 0, 0);\n"
    "    if fd < 0 { return 0; }\n"
    "    let hdr: int = Memory.Alloc(3);\n"
    "    let n: int = Kernel.Call(0, fd, hdr, 2);\n"
    "    Kernel.Call(3, fd);\n"
    "    let ok: int = 0;\n"
    "    if n == 2 {\n"
    "        if Memory.Read8(hdr) == 80 {\n"
    "            if Memory.Read8(hdr + 1) == 54 { ok = 1; } // P6\n"
    "        }\n"
    "    }\n"
    "    Memory.Free(hdr);\n"
    "    return ok;\n"
    "}\n"
    "\n"
    "fn Image.Load(path) {\n"
    "    if path == 0 { return -1; }\n"
    "    // Native PPM path\n"
    "    if pc_is_ppm(path) == 1 {\n"
    "        // Store path pointer in a global slot for Image.Show (offset 3200)\n"
    "        Memory.Write64(Rt.Global() + 3200, path);\n"
    "        Memory.Write64(Rt.Global() + 3208, 1); // kind = ppm\n"
    "        return 1;\n"
    "    }\n"
    "    // Try ImageMagick/GraphicsMagick convert → temp PPM\n"
    "    let tmp: int = Memory.Alloc(64);\n"
    "    pc_cat(tmp, 0, \"/tmp/purple-img.ppm\");\n"
    "    let pid: int = pc_spawn3(\"/usr/bin/convert\", path, \"ppm:-\", tmp);\n"
    "    // convert out-file syntax: convert in out — simpler:\n"
    "    // Actually: convert input.png /tmp/purple-img.ppm\n"
    "    if pid < 0 {\n"
    "        pid = pc_spawn2(\"/usr/bin/convert\", path, tmp);\n"
    "    }\n"
    "    if pid < 0 {\n"
    "        pid = pc_spawn2(\"/usr/bin/gm\", path, tmp); // graphicsmagick\n"
    "    }\n"
    "    if pid >= 0 { pc_waitpid(pid); }\n"
    "    if pc_is_ppm(tmp) == 1 {\n"
    "        Memory.Write64(Rt.Global() + 3200, tmp);\n"
    "        Memory.Write64(Rt.Global() + 3208, 1);\n"
    "        return 1;\n"
    "    }\n"
    "    let msg = \"[Image.Load] need PPM, or install ImageMagick convert for PNG/JPEG under GoodNative\\n\";\n"
    "    pc_write_all(2, msg, pc_strlen(msg));\n"
    "    Memory.Free(tmp);\n"
    "    return -1;\n"
    "}\n"
    "\n"
    "fn Image.Show(handle) {\n"
    "    if handle <= 0 { return -1; }\n"
    "    let path: int = Memory.Read64(Rt.Global() + 3200);\n"
    "    if path == 0 { return -1; }\n"
    "    // Reuse pure X11 path: open a window and blit PPM pixels would need a full\n"
    "    // PPM parser + X putimage. For now open with xdg-open / feh / display.\n"
    "    let r: int = pc_spawn_wait(\"/usr/bin/feh\", path);\n"
    "    if r < 0 { r = pc_spawn_wait(\"/usr/bin/display\", path); }\n"
    "    if r < 0 { r = pc_spawn_wait(\"/usr/bin/xdg-open\", path); }\n"
    "    return r;\n"
    "}\n"
    "\n"
    "// ---- Font registration: emergency only under pure path; try system path hints\n"
    "\n"
    "fn IFont(name, data, encoding) {\n"
    "    if name == 0 { return -1; }\n"
    "    // Without FreeType we cannot rasterize TTF/OTF. Accept the registration\n"
    "    // name so callers don't crash, but drawing still uses emergency font.\n"
    "    return -1;\n"
    "}\n"
    "\n"
    "fn Blow.IFont(name, data, encoding) {\n"
    "    return IFont(name, data, encoding);\n"
    "}\n"
    "\n"
    "// ---- Controlang / PurpleAPI — registry table; Call requires dlopen (GCC)\n"
    "// We keep a name→(lib,sym) table so Register succeeds; Call still needs --gcc\n"
    "// for actual .so loading unless a helper is used.\n"
    "\n"
    "fn Controlang.Native.Register(name, lib, sym) {\n"
    "    if name == 0 { return -1; }\n"
    "    if lib == 0 { return -1; }\n"
    "    if sym == 0 { return -1; }\n"
    "    // Slot 3300: simple single-entry registry for the pure path\n"
    "    Memory.Write64(Rt.Global() + 3300, name);\n"
    "    Memory.Write64(Rt.Global() + 3308, lib);\n"
    "    Memory.Write64(Rt.Global() + 3316, sym);\n"
    "    let msg = \"[Controlang] Registered \";\n"
    "    // print confirmation\n"
    "    let b: int = Memory.Alloc(pc_strlen(name) + pc_strlen(lib) + 64);\n"
    "    let o: int = pc_cat(b, 0, \"[Controlang] Registered \");\n"
    "    o = pc_cat(b, o, name);\n"
    "    o = pc_cat(b, o, \" from \");\n"
    "    o = pc_cat(b, o, lib);\n"
    "    o = pc_cat(b, o, \" (Call needs --gcc for dlopen, or use Program.ELF64.Run)\\n\");\n"
    "    pc_write_all(1, b, o);\n"
    "    Memory.Free(b);\n"
    "    return 0;\n"
    "}\n"
    "\n"
    "fn Controlang.Call(name, a0, a1, a2, a3, a4, a5) {\n"
    "    if name == 0 { return -1; }\n"
    "    let _k: int = a0 + a1 + a2 + a3 + a4 + a5;\n"
    "    if _k == -999999 { return _k; }\n"
    "    let msg = \"[Controlang.Call] in-process .so plugins need --gcc (dlopen); use Program.ELF64.Run for out-of-process plugins\\n\";\n"
    "    pc_write_all(2, msg, pc_strlen(msg));\n"
    "    return -1;\n"
    "}\n"
    "\n"
    "fn PurpleAPI.Call(name, a0, a1, a2, a3, a4, a5) {\n"
    "    return Controlang.Call(name, a0, a1, a2, a3, a4, a5);\n"
    "}\n"
    "\n"
    "// ---- Program.ELF64 — validate ELF magic, then execve (real process isolation)\n"
    "\n"
    "fn pc_is_elf64(path) {\n"
    "    let fd: int = Kernel.Call(2, path, 0, 0);\n"
    "    if fd < 0 { return 0; }\n"
    "    let hdr: int = Memory.Alloc(16);\n"
    "    let n: int = Kernel.Call(0, fd, hdr, 5);\n"
    "    Kernel.Call(3, fd);\n"
    "    let ok: int = 0;\n"
    "    if n >= 5 {\n"
    "        if Memory.Read8(hdr) == 127 {\n"
    "            if Memory.Read8(hdr + 1) == 69 {\n"
    "                if Memory.Read8(hdr + 2) == 76 {\n"
    "                    if Memory.Read8(hdr + 3) == 70 {\n"
    "                        if Memory.Read8(hdr + 4) == 2 { ok = 1; } // ELFCLASS64\n"
    "                    }\n"
    "                }\n"
    "            }\n"
    "        }\n"
    "    }\n"
    "    Memory.Free(hdr);\n"
    "    return ok;\n"
    "}\n"
    "\n"
    "fn Program.ELF64.Open(path) {\n"
    "    if path == 0 { return -1; }\n"
    "    if pc_is_elf64(path) == 0 {\n"
    "        let msg = \"[Program.ELF64] Not a valid ELF64: \";\n"
    "        let b: int = Memory.Alloc(pc_strlen(path) + 48);\n"
    "        let o: int = pc_cat(b, 0, \"[Program.ELF64] Not a valid ELF64: \");\n"
    "        o = pc_cat(b, o, path);\n"
    "        o = pc_cat(b, o, \"\\n\");\n"
    "        pc_write_all(2, b, o);\n"
    "        Memory.Free(b);\n"
    "        return -1;\n"
    "    }\n"
    "    let fd: int = Kernel.Call(2, path, 0, 0);\n"
    "    if fd < 0 { return -1; }\n"
    "    // Stash path for Run (offset 3400)\n"
    "    let pcopy: int = Memory.Alloc(pc_strlen(path) + 1);\n"
    "    pc_cat(pcopy, 0, path);\n"
    "    Memory.Write64(Rt.Global() + 3400, pcopy);\n"
    "    Memory.Write64(Rt.Global() + 3408, fd);\n"
    "    return fd;\n"
    "}\n"
    "\n"
    "fn Program.ELF64.Close(handle) {\n"
    "    if handle >= 0 { Kernel.Call(3, handle); }\n"
    "    let p: int = Memory.Read64(Rt.Global() + 3400);\n"
    "    if p != 0 { Memory.Free(p); Memory.Write64(Rt.Global() + 3400, 0); }\n"
    "    return 0;\n"
    "}\n"
    "\n"
    "fn Program.ELF64.Run(handle_or_path) {\n"
    "    let path: int = 0;\n"
    "    if handle_or_path < 0 { return -1; }\n"
    "    // If it looks like a small fd, use stashed path; otherwise treat as path pointer\n"
    "    if handle_or_path < 1024 {\n"
    "        path = Memory.Read64(Rt.Global() + 3400);\n"
    "        if path == 0 { return -1; }\n"
    "    } else {\n"
    "        path = handle_or_path;\n"
    "    }\n"
    "    if pc_is_elf64(path) == 0 { return -1; }\n"
    "    // Make executable if needed, then execve in a child and wait\n"
    "    Kernel.Call(90, path, 493); // chmod 0755\n"
    "    let pid: int = pc_spawn(path, 0);\n"
    "    if pid < 0 { return -1; }\n"
    "    return pc_waitpid(pid);\n"
    "}\n"
    "\n"
    "fn Program.Open(path) { return Program.ELF64.Open(path); }\n"
    "fn Program.Run(h) { return Program.ELF64.Run(h); }\n"
    "fn Program.Close(h) { return Program.ELF64.Close(h); }\n"
    "fn Program.ELF64.Exec(h) { return Program.ELF64.Run(h); }\n"
    "\n"
    "// ---- CD / USB sector reads\n"
    "\n"
    "fn pc_dev_read_sector(dev, lba, buf, kind) {\n"
    "    if dev == 0 { return -1; }\n"
    "    if buf == 0 { return -1; }\n"
    "    if kind == 0 { return -1; }\n"
    "    let fd: int = Kernel.Call(2, dev, 0, 0);\n"
    "    if fd < 0 { return -1; }\n"
    "    let off: int = lba * 2048;\n"
    "    let n: int = Kernel.Call(17, fd, buf, 2048, off);\n"
    "    Kernel.Call(3, fd);\n"
    "    if n < 0 { return -1; }\n"
    "    return n;\n"
    "}\n"
    "\n"
    "fn CD.ReadSector(lba, buf) {\n"
    "    return pc_dev_read_sector(\"/dev/sr0\", lba, buf, \"CD\");\n"
    "}\n"
    "\n"
    "fn USB.ReadSector(lba, buf) {\n"
    "    return pc_dev_read_sector(\"/dev/sdb\", lba, buf, \"USB\");\n"
    "}\n"
    "\n"
    "fn CD.ReadSectorTo(lba, outpath) {\n"
    "    if outpath == 0 { return -1; }\n"
    "    let buf: int = Memory.Alloc(2048);\n"
    "    let n: int = CD.ReadSector(lba, buf);\n"
    "    if n > 0 {\n"
    "        let fd: int = Kernel.Call(2, outpath, 577, 420);\n"
    "        if fd >= 0 { pc_write_all(fd, buf, n); Kernel.Call(3, fd); }\n"
    "    }\n"
    "    Memory.Free(buf);\n"
    "    return n;\n"
    "}\n"
    "\n"
    "fn USB.ReadSectorTo(lba, outpath) {\n"
    "    if outpath == 0 { return -1; }\n"
    "    let buf: int = Memory.Alloc(2048);\n"
    "    let n: int = USB.ReadSector(lba, buf);\n"
    "    if n > 0 {\n"
    "        let fd: int = Kernel.Call(2, outpath, 577, 420);\n"
    "        if fd >= 0 { pc_write_all(fd, buf, n); Kernel.Call(3, fd); }\n"
    "    }\n"
    "    Memory.Free(buf);\n"
    "    return n;\n"
    "}\n"
    "\n"
    "fn CD.Read(path, buf, max) { return File.Read(path, buf, max); }\n"
    "fn USB.Read(path, buf, max) { return File.Read(path, buf, max); }\n"
    "\n"
    "// ---- GUI.NativeWindow / Kustom / Decorationless → pure X11 Blow\n"
    "\n"
    "fn GUI.NativeWindow(w, h, title) {\n"
    "    return Blow.Window(w, h, title);\n"
    "}\n"
    "\n"
    "fn Kustom.GUI.MakeWindow(spec) {\n"
    "    if spec == 0 { return Blow.Window(640, 400, \"Kustom\"); }\n"
    "    return Blow.Window(640, 400, spec);\n"
    "}\n"
    "\n"
    "fn Blow.Decorationless.Window(w, h, title) {\n"
    "    return Blow.Window(w, h, title);\n"
    "}\n"
    "\n";
